/**
 * Every admin page, rendered against REAL backend responses (generated by
 * backend/tests/test_dump_admin_fixtures.py: DUMP_FIXTURES=1 pytest ...). A request the fixtures don't cover,
 * an error screen, or missing real data fails the test. A second pass serves empty lists to check empty states.
 */
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { render, screen, waitFor, within } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { createMemoryRouter, RouterProvider } from "react-router-dom";
import { beforeEach, describe, expect, it, vi } from "vitest";
import fixtures from "@/modules/admin/__fixtures__/api.json";
import { adminRoutes } from "@/modules/admin/routes";
import { mockFetch, signIn } from "@/test/utils";

vi.mock("@/shared/components/map", () => ({
  coords: (lat: unknown, lng: unknown) => (lat == null || lng == null ? null : { lat: Number(lat), lng: Number(lng) }),
  MapView: ({ points }: { points: { id: string; label: string }[] }) => (
    <ul aria-label="Map points">{points.map((p) => <li key={p.id}>{p.label}</li>)}</ul>
  ),
}));

type Fx = Record<string, unknown>;
const FX = fixtures as Fx;
const ids = FX._ids as { order: string; shop: string; rider: string; complaint: string };

/** Serves a fixture for an admin GET: exact path+query first, then the bare path. */
function serve(empty = false) {
  const unmatched: string[] = [];
  const calls = mockFetch((url, init) => {
    const u = new URL(url, "http://x");
    const method = init?.method ?? "GET";
    if (method !== "GET") return { body: {} };
    const p = u.pathname.replace(/^\/api\/v1\/admin/, "");
    const key = [p + u.search, p].find((k) => k in FX);
    if (!key) {
      unmatched.push(`${method} ${p}${u.search}`);
      return { status: 404, body: { detail: "Not Found" } };
    }
    const body = FX[key];
    return { body: empty && Array.isArray(body) ? [] : body };
  });
  return { calls, unmatched };
}

function renderAdmin(path: string) {
  const router = createMemoryRouter([{ path: "/admin/*", children: adminRoutes }], { initialEntries: [path] });
  const qc = new QueryClient({ defaultOptions: { queries: { retry: false } } });
  render(<QueryClientProvider client={qc}><RouterProvider router={router} /></QueryClientProvider>);
  return router;
}

const order = (FX["/orders"] as { code: string }[])[0]!;

beforeEach(() => signIn("admin"));

describe("admin pages with real data", () => {
  it.each([
    ["/admin", [/Live/i]],
    ["/admin/map", ["Sample College (dev)", "Quick Prints"]],
    ["/admin/orders", [order.code]],
    ["/admin/shops", ["Quick Prints"]],
    ["/admin/riders", ["Kumar"]],
    ["/admin/colleges", ["Sample College (dev)"]],
    ["/admin/finance", [/Gross|Revenue/i]],
    ["/admin/settlements", ["Quick Prints"]],
    ["/admin/audit", [/Audit/i]],
  ] as const)("%s renders real data without errors", async (path, expected) => {
    const { unmatched } = serve();
    renderAdmin(path);
    for (const text of expected) expect((await screen.findAllByText(text, {}, { timeout: 4000 })).length).toBeGreaterThan(0);
    await waitFor(() => expect(screen.queryByText("Something went wrong")).not.toBeInTheDocument());
    expect(unmatched).toEqual([]);
  });

  it.each(["/admin", "/admin/orders", "/admin/shops", "/admin/riders", "/admin/finance", "/admin/settlements", "/admin/audit"])(
    "%s shows designed empty states with no data",
    async (path) => {
      const { unmatched } = serve(true);
      renderAdmin(path);
      await screen.findAllByRole("heading", {}, { timeout: 4000 });
      await new Promise((r) => setTimeout(r, 50));
      expect(screen.queryByText("Something went wrong")).not.toBeInTheDocument();
      expect(unmatched).toEqual([]);
    },
  );

  it("sidebar badges count real pending approvals", async () => {
    serve();
    renderAdmin("/admin");
    const nav = (await screen.findAllByRole("navigation", { name: "Main" }))[0]!;
    await waitFor(() => expect(within(nav).getByRole("link", { name: /Printing Shops\s*1/ })).toBeInTheDocument());
    expect(within(nav).getByRole("link", { name: /Delivery Partners\s*1/ })).toBeInTheDocument();
  });

  it("finds an order and opens its detail with the print specs", async () => {
    const { calls } = serve();
    renderAdmin("/admin/orders");
    await userEvent.click(await screen.findByText(order.code, {}, { timeout: 4000 }));
    expect((await screen.findAllByText(/notes\.pdf/)).length).toBeGreaterThan(0);
    expect(calls.some((c) => c.url.includes(`/admin/orders/${ids.order}`))).toBe(true);
  });
});
